import {polygon,edges,segments,distance,mix,parameter,on} from './geometry.js';
export function entranceGeometry(e,shapes){if(!e.anchor)return null;const shape=shapes.find(s=>s.id===e.anchor.owner&&s.layer==='foundation');if(!shape)return null;const edge=edges(polygon(shape))[e.anchor.edge];if(!edge)return null;const length=distance(edge.a,edge.b),half=e.width/length/2,t=e.anchor.t;if(t-half< -1e-6||t+half>1+1e-6)return null;return {a:mix(edge.a,edge.b,t-half),b:mix(edge.a,edge.b,t+half),center:mix(edge.a,edge.b,t),edge,length,lo:t-half,hi:t+half,angle:Math.atan2(edge.b.y-edge.a.y,edge.b.x-edge.a.x)};}
export function supported(e,shapes,walls){const g=entranceGeometry(e,shapes);if(!g)return false;const ranges=walls.filter(w=>w.enabled&&on(w.a,g.edge.a,g.edge.b)&&on(w.b,g.edge.a,g.edge.b)).map(w=>[parameter(w.a,g.edge.a,g.edge.b),parameter(w.b,g.edge.a,g.edge.b)].sort((a,b)=>a-b)).sort((a,b)=>a[0]-b[0]);let end=g.lo;for(const [a,b] of ranges){if(a>end+1e-6)continue;if(b>=end)end=b;if(end>=g.hi-1e-6)return true;}return false;}
export function entrancesValid(s){if(!Array.isArray(s.entrances)||s.entrances.length>200||new Set(s.entrances.map(e=>e?.id)).size!==s.entrances.length)return false;const walls=segments(s.shapes.filter(o=>o.layer==='foundation'),s.walls);for(const e of s.entrances){if(!e||typeof e.id!=='string'||!['shutter','swing'].includes(e.type)||!Number.isFinite(e.width)||e.width<=0||e.width>1000||![0,90,180,270].includes(e.rotation))return false;if(e.anchor!==null&&(!e.anchor||typeof e.anchor.owner!=='string'||!Number.isInteger(e.anchor.edge)||!Number.isFinite(e.anchor.t)||!supported(e,s.shapes,walls)))return false;}const placed=s.entrances.filter(e=>e.anchor);for(let i=0;i<placed.length;i++)for(let j=i+1;j<placed.length;j++){const a=entranceGeometry(placed[i],s.shapes),b=entranceGeometry(placed[j],s.shapes);if(on(b.a,a.edge.a,a.edge.b)&&on(b.b,a.edge.a,a.edge.b)){const lo=Math.min(parameter(b.a,a.edge.a,a.edge.b),parameter(b.b,a.edge.a,a.edge.b)),hi=Math.max(parameter(b.a,a.edge.a,a.edge.b),parameter(b.b,a.edge.a,a.edge.b));if(Math.min(a.hi,hi)-Math.max(a.lo,lo)>1e-6)return false;}}return true;}
export function nearestPlacement(e,p,shapes,walls,maxDistance=Infinity){let best=null;for(const o of shapes.filter(s=>s.layer==='foundation'))for(const [index,edge]of edges(polygon(o)).entries()){const length=distance(edge.a,edge.b),half=e.width/length/2;if(half>.5+1e-6)continue;const ranges=walls.filter(w=>w.enabled&&on(w.a,edge.a,edge.b)&&on(w.b,edge.a,edge.b)).map(w=>[parameter(w.a,edge.a,edge.b),parameter(w.b,edge.a,edge.b)].sort((a,b)=>a-b)).sort((a,b)=>a[0]-b[0]);const runs=[];for(const r of ranges){const last=runs.at(-1);if(last&&r[0]<=last[1]+1e-6)last[1]=Math.max(last[1],r[1]);else runs.push([...r]);}for(const [lo,hi]of runs){if(hi-lo<half*2-1e-6)continue;const t=Math.max(lo+half,Math.min(hi-half,parameter(p,edge.a,edge.b))),q=mix(edge.a,edge.b,t),d=distance(p,q);if(d<=maxDistance&&(!best||d<best.distance))best={anchor:{owner:o.id,edge:index,t},distance:d};}}return best?.anchor||null;}
